insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('citas-consultorio','salud',array[]::text[],'Menos citas perdidas en un consultorio','Explora cómo diseñar recordatorios y reprogramaciones para un consultorio pequeño, probándolos con un caso simulado.','Prototipo','~15 h',15,array['Procesos','Atención al paciente']::text[],array['resolver','crear']::text[],'ficticios',NULL,'medicina enfermeria psicologia ingenieria de sistemas ingenieria industrial administracion mapeo de procesos redaccion clara para pacientes analisis basico de datos hoja de calculo diagramas de flujo mensajeria o correo para la simulacion',$f00sld${"id": "citas-consultorio", "area": "salud", "areas2": [], "titulo": "Menos citas perdidas en un consultorio", "resumen": "Explora cómo diseñar recordatorios y reprogramaciones para un consultorio pequeño, probándolos con un caso simulado.", "tipo": "Prototipo", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Procesos", "Atención al paciente"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: puedes hacerlo sin pedir permiso a nadie", "carreras": ["Medicina", "Enfermería", "Psicología", "Ingeniería de Sistemas", "Ingeniería Industrial", "Administración"], "problema": ["Cuando un paciente falta a su cita sin avisar, se pierde un espacio que otra persona pudo usar y el consultorio pierde tiempo y dinero."], "desarrollar": ["Un flujo de recordatorios antes de la cita, una forma fácil de confirmar o reprogramar, y un registro simple de cuántas citas se recuperan. Se puede probar con datos inventados."], "ampliaciones": [{"titulo": "Otro público", "aporta": "Explora cómo adaptar los mensajes para personas mayores o que casi no usan el celular."}, {"titulo": "Otra mirada", "aporta": "Descubre cuánto tiempo y dinero se pierde por cada cita que nadie ocupa, y qué ahorro traería recuperarla."}, {"titulo": "Otro formato", "aporta": "Imagina una forma de reprogramar la cita desde un enlace, sin llamar a nadie."}], "objetivos": ["Describir cómo se agenda y se confirma una cita hoy.", "Diseñar los mensajes y el momento en que se envían.", "Medir con un caso simulado cuántas citas se podrían recuperar."], "habilidades": ["Mapeo de procesos", "Redacción clara para pacientes", "Análisis básico de datos"], "herramientas": ["Hoja de cálculo", "Diagramas de flujo", "Mensajería o correo para la simulación"], "lineamientos": ["Usa datos ficticios: nunca información real de pacientes.", "Los mensajes deben ser breves y respetuosos.", "Aclara que es una simulación y no un servicio médico."], "otroSector": "Sirve igual para peluquerías, academias, talleres mecánicos o cualquier negocio que trabaje con citas."}$f00sld$::jsonb,0),
('por-que-se-abandona-un-tratamiento-antes-de-terminarlo','salud',array['sociedad']::text[],'¿Por qué se abandona un tratamiento antes de terminarlo?','Descubre qué razones llevan a una persona a dejar un tratamiento a medias, como el costo, los efectos molestos, el olvido o la falta de información, y qué podría ayudarla a terminarlo.','Investigación','~15 h',15,array['Adherencia','Atención al paciente']::text[],array['investigar','resolver']::text[],'publicos',NULL,'medicina enfermeria psicologia trabajo social administracion ingenieria industrial estadistica educacion analisis de informacion. clasificacion de casos. comprension de comportamientos. sintesis y redaccion. documento o presentacion. hoja de calculo para clasificar las situaciones. busqueda de informes publicos de organismos de salud.',$f01sld${"id": "por-que-se-abandona-un-tratamiento-antes-de-terminarlo", "area": "salud", "areas2": ["sociedad"], "titulo": "¿Por qué se abandona un tratamiento antes de terminarlo?", "resumen": "Descubre qué razones llevan a una persona a dejar un tratamiento a medias, como el costo, los efectos molestos, el olvido o la falta de información, y qué podría ayudarla a terminarlo.", "tipo": "Investigación", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Adherencia", "Atención al paciente"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Medicina", "Enfermería", "Psicología", "Trabajo Social", "Administración", "Ingeniería Industrial", "Estadística", "Educación"], "problema": ["Muchos tratamientos, desde unos días de medicamento hasta un control que dura meses, fracasan no porque no sirvan sino porque la persona los deja antes de tiempo. A veces mejora y cree que ya no hace falta; otras, no puede pagarlo, le caen mal o no entendió cuánto debía durar.", "Quienes diseñan los servicios suelen enterarse tarde. Sin entender las razones reales es difícil crear recordatorios, explicaciones o apoyos que de verdad funcionen."], "desarrollar": ["Reúne entre cinco y ocho situaciones, tomadas de estudios públicos, de notas informativas de instituciones de salud o inventadas con base en ellas, y agrúpalas por tipo de razón: económica, de información, de efectos, de tiempo o de motivación. Para cada grupo anota quién podría ayudar y cómo.", "El resultado puede ser un mapa de razones con ejemplos y una propuesta breve de qué haría diferente un servicio de salud en cada caso."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara cómo cambian las razones entre un tratamiento corto y uno que dura meses."}, {"titulo": "Otro formato", "aporta": "convierte el mapa en un cuestionario breve que un servicio de salud podría usar para detectar quién corre más riesgo de abandonar."}, {"titulo": "Otro público", "aporta": "adapta las ideas al caso de personas mayores, que suelen tomar varios medicamentos a la vez."}], "objetivos": ["Identificar las razones por las que se abandona un tratamiento.", "Agrupar las razones en categorías claras.", "Relacionar cada categoría con una ayuda posible.", "Presentar los hallazgos de forma comprensible para cualquier persona."], "habilidades": ["Análisis de información.", "Clasificación de casos.", "Comprensión de comportamientos.", "Síntesis y redacción."], "herramientas": ["Documento o presentación.", "Hoja de cálculo para clasificar las situaciones.", "Búsqueda de informes públicos de organismos de salud."], "lineamientos": ["No uses historias clínicas ni datos de pacientes reales, ni preguntes por diagnósticos a quien no quiera contarlos. Trabaja con casos públicos o inventados.", "No indiques cuánto debe durar un tratamiento ni qué debe tomar nadie: eso lo decide un profesional de la salud."], "otroSector": "El mismo análisis ayuda a entender por qué la gente abandona un gimnasio, un curso o un plan de ahorro."}$f01sld$::jsonb,1),
('un-recordatorio-de-medicamentos-que-de-verdad-se-cumpla','salud',array['tecnologia']::text[],'Un recordatorio de medicamentos que de verdad se cumpla','Imagina cómo debería ser un recordatorio de medicamentos para que alguien lo use semana tras semana, y pruébalo con una persona o con un caso inventado.','Prototipo','~15 h',15,array['Hábitos','Experiencia de usuario']::text[],array['crear','resolver']::text[],'ficticios',NULL,'ingenieria de sistemas ingenieria de software medicina enfermeria psicologia diseno grafico ingenieria industrial administracion diseno centrado en las personas. redaccion de mensajes breves y claros. observacion de habitos. prototipado. papel y lapiz, o una herramienta de maquetas. hoja de calculo para simular las alarmas. mensajeria o correo para la prueba.',$f02sld${"id": "un-recordatorio-de-medicamentos-que-de-verdad-se-cumpla", "area": "salud", "areas2": ["tecnologia"], "titulo": "Un recordatorio de medicamentos que de verdad se cumpla", "resumen": "Imagina cómo debería ser un recordatorio de medicamentos para que alguien lo use semana tras semana, y pruébalo con una persona o con un caso inventado.", "tipo": "Prototipo", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Hábitos", "Experiencia de usuario"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Medicina", "Enfermería", "Psicología", "Diseño Gráfico", "Ingeniería Industrial", "Administración"], "problema": ["Una alarma en el celular parece suficiente, pero muchas personas la apagan, la ignoran o se cansan de ella. Cuando el tratamiento es largo o hay varios medicamentos a distintas horas, olvidar una toma es lo más normal del mundo.", "Los recordatorios que existen suelen pensarse para quien ya tiene el hábito. Casi nadie diseña pensando en quien se confunde, viaja, trabaja por turnos o no usa bien el celular."], "desarrollar": ["Elige un perfil inventado, por ejemplo una persona mayor con tres medicamentos o un estudiante con un tratamiento de dos semanas, y describe cuándo y por qué olvida. Diseña un recordatorio que encaje en su rutina: qué avisa, a qué hora, cómo se confirma y qué pasa si no se confirma.", "Puede ser un boceto en papel, una hoja de cálculo con alarmas simuladas o una maqueta en una herramienta de diseño. Pruébalo con una persona cercana y anota en qué momento se frustró."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta el recordatorio para alguien que casi no usa el celular, con una opción en papel o por llamada."}, {"titulo": "Otra mirada", "aporta": "mide cuántos olvidos evita cada mejora que probaste y cuál se siente menos molesta."}, {"titulo": "Un paso más", "aporta": "piensa en qué pasa si quien cuida a la persona también recibe el aviso."}], "objetivos": ["Describir cuándo y por qué se olvidan las tomas.", "Diseñar un recordatorio adaptado a un perfil concreto.", "Probarlo con una persona o un caso simulado.", "Ajustarlo según lo que resulte incómodo o confuso."], "habilidades": ["Diseño centrado en las personas.", "Redacción de mensajes breves y claros.", "Observación de hábitos.", "Prototipado."], "herramientas": ["Papel y lápiz, o una herramienta de maquetas.", "Hoja de cálculo para simular las alarmas.", "Mensajería o correo para la prueba."], "lineamientos": ["Usa solo casos inventados o con personas que acepten participar; no incluyas nombres reales de medicamentos con dosis ni datos de salud de nadie.", "Aclara que el prototipo no sustituye las indicaciones del profesional de salud: solo ayuda a recordar lo que ya se indicó."], "otroSector": "Sirve igual para recordar pagos, entregas, riegos de un huerto o el mantenimiento de un equipo."}$f02sld$::jsonb,2),
('como-hacer-que-haya-sangre-cuando-se-necesita','salud',array['tecnologia']::text[],'¿Cómo hacer que haya sangre cuando se necesita?','Diseña cómo se podría organizar una campaña de donación de sangre para que cada vez haya más donantes y menos desperdicio, y descubre por qué algunas personas sí donan y otras no.','Plan','~20 h',20,array['Campañas','Organización','Voluntariado']::text[],array['resolver','crear']::text[],'ficticios',NULL,'administracion ingenieria industrial ingenieria de sistemas comunicaciones medicina enfermeria trabajo social estadistica organizacion de eventos. mapeo de procesos. comunicacion para convocar y agradecer. medicion de resultados. hoja de calculo o gestor de tareas. diagramas de flujo. herramientas para disenar afiches o mensajes.',$f03sld${"id": "como-hacer-que-haya-sangre-cuando-se-necesita", "area": "salud", "areas2": ["tecnologia"], "titulo": "¿Cómo hacer que haya sangre cuando se necesita?", "resumen": "Diseña cómo se podría organizar una campaña de donación de sangre para que cada vez haya más donantes y menos desperdicio, y descubre por qué algunas personas sí donan y otras no.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Campañas", "Organización", "Voluntariado"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Administración", "Ingeniería Industrial", "Ingeniería de Sistemas", "Comunicaciones", "Medicina", "Enfermería", "Trabajo Social", "Estadística"], "problema": ["La sangre no se puede fabricar: depende de que alguien decida donar y de que llegue en el momento y lugar adecuados. Muchos servicios de salud viven con reservas justas, y cada campaña mal organizada significa filas, personas que se van sin donar y donantes que no vuelven.", "Además, no basta con convocar: hay que explicar los requisitos, citar a las personas, atenderlas bien y recordarles volver. Cada una de esas etapas puede mejorarse."], "desarrollar": ["Describe, con un caso inventado, cómo se desarrolla hoy una campaña desde la convocatoria hasta que el donante se va, y marca dónde se pierde gente o tiempo. Después diseña una versión mejorada: cómo convocar, cómo organizar los turnos, cómo recibir a las personas y cómo agradecerles.", "El resultado puede ser un plan de campaña con cronograma, roles, mensajes y una forma sencilla de medir cuántas personas llegaron, donaron y volvieron."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "investiga qué motiva a las personas a donar por primera vez y qué las hace volver, con estudios públicos o encuestas breves."}, {"titulo": "Otro formato", "aporta": "convierte el plan en una pequeña herramienta de registro de turnos y recordatorios para los organizadores."}, {"titulo": "Un paso más", "aporta": "adapta el plan a una campaña dentro de una universidad o una empresa."}], "objetivos": ["Describir las etapas de una campaña de donación.", "Identificar dónde se pierden personas o tiempo.", "Diseñar un plan de campaña mejorado.", "Definir cómo medir si funcionó."], "habilidades": ["Organización de eventos.", "Mapeo de procesos.", "Comunicación para convocar y agradecer.", "Medición de resultados."], "herramientas": ["Hoja de cálculo o gestor de tareas.", "Diagramas de flujo.", "Herramientas para diseñar afiches o mensajes."], "lineamientos": ["Trabaja con un caso inventado: no necesitas datos reales de donantes ni ayuda de un banco de sangre para empezar.", "No indiques quién puede o no puede donar: los requisitos los define el servicio de salud. Remite siempre a esa fuente oficial."], "otroSector": "La misma lógica sirve para organizar una colecta, una jornada de vacunación, una feria o un voluntariado."}$f03sld$::jsonb,3),
('se-entiende-lo-que-dijo-el-medico-antes-y-despues-de-la-consulta','salud',array['arte']::text[],'¿Se entiende lo que dijo el médico? Antes y después de la consulta','Mide qué tan fácil es entender las indicaciones de una receta o de una consulta, y propón cómo explicarlas para que cualquiera pueda seguirlas.','Análisis','~15 h',15,array['Comunicación','Atención al paciente']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'medicina enfermeria psicologia comunicaciones educacion diseno grafico trabajo social derecho comunicacion clara para publico general. observacion y entrevista breve. analisis de textos. diseno de materiales explicativos. documento o presentacion. hoja de calculo para anotar resultados. herramientas para disenar esquemas o iconos.',$f04sld${"id": "se-entiende-lo-que-dijo-el-medico-antes-y-despues-de-la-consulta", "area": "salud", "areas2": ["arte"], "titulo": "¿Se entiende lo que dijo el médico? Antes y después de la consulta", "resumen": "Mide qué tan fácil es entender las indicaciones de una receta o de una consulta, y propón cómo explicarlas para que cualquiera pueda seguirlas.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Comunicación", "Atención al paciente"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Medicina", "Enfermería", "Psicología", "Comunicaciones", "Educación", "Diseño Gráfico", "Trabajo Social", "Derecho"], "problema": ["Una persona sale de la consulta con una receta, una cita para después y unas pocas frases dichas con prisa. En casa, ya no recuerda si el medicamento era antes o después de comer, por cuántos días, o qué hacer si se siente peor.", "Cuando no se entiende, ocurren errores: se toma de más, de menos o a la hora equivocada, o se deja el tratamiento. Casi nunca es por descuido: la información simplemente no fue clara."], "desarrollar": ["Toma tres o cuatro recetas o indicaciones inventadas, escritas como las suelen escribir, y pide a algunas personas que te expliquen con sus palabras qué entendieron. Anota qué se entendió, qué no y dónde hubo confusión.", "Con lo que encuentres, propón una versión más clara de las indicaciones: otro orden, otras palabras, un esquema o un ícono. El resultado puede ser una comparación de antes y después más una guía de buenas prácticas para quien explica."], "ampliaciones": [{"titulo": "Otro público", "aporta": "prueba con personas mayores o con quienes tienen poca experiencia leyendo textos técnicos."}, {"titulo": "Otro formato", "aporta": "convierte las indicaciones en una tarjeta o un cartel que pueda pegarse en la puerta de la cocina."}, {"titulo": "Una prueba", "aporta": "mide cuántos errores desaparecen cuando se usa la versión mejorada."}], "objetivos": ["Identificar qué partes de las indicaciones se entienden menos.", "Entender por qué ocurre la confusión.", "Proponer una versión más clara.", "Comprobar con otras personas que la nueva versión mejora."], "habilidades": ["Comunicación clara para público general.", "Observación y entrevista breve.", "Análisis de textos.", "Diseño de materiales explicativos."], "herramientas": ["Documento o presentación.", "Hoja de cálculo para anotar resultados.", "Herramientas para diseñar esquemas o íconos."], "lineamientos": ["Usa recetas e indicaciones inventadas: nunca pidas ni muestres documentos médicos reales de nadie.", "No cambies el sentido de una indicación; el objetivo es explicarla mejor, no modificarla. Cualquier duda sobre una indicación se consulta con quien la dio."], "otroSector": "La misma idea sirve para manuales de uso, contratos, términos de un servicio o instrucciones de un trámite."}$f04sld$::jsonb,4),
('cuanto-tiempo-se-pierde-esperando-atencion','salud',array['industria']::text[],'¿Cuánto tiempo se pierde esperando atención?','Mide cuánto dura realmente una espera en un servicio de salud y descubre dónde se pierde el tiempo, qué la hace más pesada y qué podría hacerla más llevadera.','Análisis','~20 h',20,array['Procesos','Experiencia del paciente']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria industrial administracion ingenieria de sistemas medicina enfermeria estadistica psicologia arquitectura medicion de tiempos. analisis de procesos. analisis basico de datos. diseno de servicios. cronometro o notas en el celular. hoja de calculo. diagramas de flujo.',$f05sld${"id": "cuanto-tiempo-se-pierde-esperando-atencion", "area": "salud", "areas2": ["industria"], "titulo": "¿Cuánto tiempo se pierde esperando atención?", "resumen": "Mide cuánto dura realmente una espera en un servicio de salud y descubre dónde se pierde el tiempo, qué la hace más pesada y qué podría hacerla más llevadera.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Procesos", "Experiencia del paciente"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Ingeniería Industrial", "Administración", "Ingeniería de Sistemas", "Medicina", "Enfermería", "Estadística", "Psicología", "Arquitectura"], "problema": ["Esperar es parte de cualquier atención, pero casi nunca se mide. Se sabe que «se demora mucho», no cuánto, ni en qué etapa: el registro, la fila de la ventanilla, la sala o la consulta.", "La espera también se vive distinto según el lugar: una sala sin sillas, sin información sobre cuánto falta o con ruido hace que el mismo tiempo se sienta mucho más largo."], "desarrollar": ["Si tienes oportunidad, anota con permiso tus propios tiempos y los de alguien cercano en una visita a un servicio, desde que llegas hasta que sales; si no, inventa un caso y usa datos públicos. Divide el tiempo por etapas y busca dónde se acumula.", "Con eso propón dos o tres cambios simples, como mostrar cuánto falta, reordenar las colas o hacer más cómoda la sala, y explica qué efecto tendrían. El resultado puede ser un cuadro de tiempos por etapa y una propuesta breve."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara cómo cambia la percepción de la espera entre quienes tienen información sobre cuánto falta y quienes no."}, {"titulo": "Otro formato", "aporta": "simula en una hoja de cálculo cómo cambiaría la espera si se reorganizaran los turnos."}, {"titulo": "Un paso más", "aporta": "diseña cómo debería ser una sala de espera cómoda para niños, adultos mayores o personas con dolor."}], "objetivos": ["Medir o estimar el tiempo de cada etapa de una atención.", "Identificar dónde se acumula la espera.", "Proponer cambios sencillos.", "Explicar qué efecto tendrían."], "habilidades": ["Medición de tiempos.", "Análisis de procesos.", "Análisis básico de datos.", "Diseño de servicios."], "herramientas": ["Cronómetro o notas en el celular.", "Hoja de cálculo.", "Diagramas de flujo."], "lineamientos": ["Pide permiso antes de medir o anotar en un servicio de salud, y no registres nombres ni datos de nadie. Si no es posible, trabaja con un caso inventado.", "No interrumpas la atención ni fotografíes a las personas: el objetivo es entender el proceso, no evaluar a quien atiende."], "otroSector": "El mismo análisis sirve para una ventanilla de banco, una cafetería, un trámite público o un aeropuerto."}$f05sld$::jsonb,5),
('que-obstaculos-encuentra-una-persona-para-llegar-a-un-servicio-de-salud','salud',array['sociedad']::text[],'¿Qué obstáculos encuentra una persona para llegar a un servicio de salud?','Reconstruye el camino de una persona para atenderse, desde que siente que lo necesita hasta que la atienden, y descubre dónde se atasca: distancia, costo, tiempo, trámites o miedo.','Investigación','~20 h',20,array['Acceso','Comunidad']::text[],array['investigar','resolver']::text[],'publicos',NULL,'trabajo social medicina enfermeria sociologia ingenieria industrial ingenieria civil administracion economia investigacion social. mapeo de recorridos. analisis de datos publicos. pensamiento critico. documento o presentacion. hoja de calculo para costos y tiempos. mapas en linea y portales de datos abiertos.',$f06sld${"id": "que-obstaculos-encuentra-una-persona-para-llegar-a-un-servicio-de-salud", "area": "salud", "areas2": ["sociedad"], "titulo": "¿Qué obstáculos encuentra una persona para llegar a un servicio de salud?", "resumen": "Reconstruye el camino de una persona para atenderse, desde que siente que lo necesita hasta que la atienden, y descubre dónde se atasca: distancia, costo, tiempo, trámites o miedo.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Acceso", "Comunidad"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Trabajo Social", "Medicina", "Enfermería", "Sociología", "Ingeniería Industrial", "Ingeniería Civil", "Administración", "Economía"], "problema": ["Acceder a la salud no es solo que exista un establecimiento: hay que saber a cuál ir, llegar, pagar, conseguir una cita y que alguien atienda. Basta que falle uno de esos pasos para que la persona no se atienda.", "Esos obstáculos cambian entre una ciudad, un distrito pobre o un pueblo, y no se ven desde afuera. Quienes planifican suelen medir cuántos servicios hay, no cuántas personas realmente llegan a usarlos."], "desarrollar": ["Elige una comunidad real o inventada y reconstruye, con datos públicos y casos hipotéticos, el recorrido de tres perfiles distintos: una persona adulta que trabaja, una madre con hijos y una persona mayor. Marca en cada recorrido los obstáculos y cuánto tiempo o dinero cuestan.", "Con eso arma un mapa de obstáculos y propón una o dos mejoras posibles. El resultado puede ser un esquema visual con los tres recorridos y una propuesta."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "calcula cuánto cuesta llegar al servicio, sumando pasajes, horas sin trabajar y comida."}, {"titulo": "Otro público", "aporta": "repite el análisis para una persona con discapacidad o para alguien que no domina el idioma de su localidad."}, {"titulo": "Un paso más", "aporta": "revisa si la información disponible sobre dónde atenderse es fácil de encontrar."}], "objetivos": ["Reconstruir el recorrido de una persona hasta una atención.", "Identificar los obstáculos de cada etapa.", "Comparar recorridos de personas distintas.", "Proponer mejoras."], "habilidades": ["Investigación social.", "Mapeo de recorridos.", "Análisis de datos públicos.", "Pensamiento crítico."], "herramientas": ["Documento o presentación.", "Hoja de cálculo para costos y tiempos.", "Mapas en línea y portales de datos abiertos."], "lineamientos": ["Usa datos públicos y perfiles inventados. Si conversas con alguien, que sea con su consentimiento y sin anotar su nombre ni su condición de salud.", "Describe las dificultades sin culpar a las personas ni al personal de salud: muchas veces el problema está en cómo está organizado el servicio."], "otroSector": "El mismo análisis sirve para el acceso a un banco, a la justicia, a la educación o al transporte."}$f06sld$::jsonb,6),
('salud-y-bolsillo-que-tan-accesible-es-la-atencion-cuando-hay-poco-dinero','salud',array['negocios']::text[],'Salud y bolsillo: ¿qué tan accesible es la atención cuando hay poco dinero?','Calcula cuánto puede costar atenderse en distintas situaciones y descubre cuándo el dinero se vuelve una barrera para cuidar la salud.','Análisis','~15 h',15,array['Costos','Acceso']::text[],array['investigar','resolver']::text[],'publicos',NULL,'economia administracion contabilidad estadistica trabajo social medicina sociologia derecho calculo de costos. analisis comparativo. lectura de datos publicos. comunicacion de resultados. hoja de calculo. portales de precios y tarifas publicas. documento o presentacion.',$f07sld${"id": "salud-y-bolsillo-que-tan-accesible-es-la-atencion-cuando-hay-poco-dinero", "area": "salud", "areas2": ["negocios"], "titulo": "Salud y bolsillo: ¿qué tan accesible es la atención cuando hay poco dinero?", "resumen": "Calcula cuánto puede costar atenderse en distintas situaciones y descubre cuándo el dinero se vuelve una barrera para cuidar la salud.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Costos", "Acceso"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Economía", "Administración", "Contabilidad", "Estadística", "Trabajo Social", "Medicina", "Sociología", "Derecho"], "problema": ["Una consulta, unos análisis o un medicamento pueden parecer pequeños gastos, pero para muchas familias compiten con la comida, el transporte o la renta. Cuando el presupuesto no alcanza, la salud es de lo primero que se posterga.", "Casi nadie suma el costo completo: además de la atención están el pasaje, las horas que no se trabaja y el acompañante. Sin esa cuenta, es imposible saber qué tan accesible es en la práctica."], "desarrollar": ["Elige dos o tres situaciones comunes, como un resfrío fuerte, un control del niño o una consulta por dolor persistente, y calcula con precios públicos o inventados cuánto costaría atenderse por distintas vías. Incluye todo lo que gasta la persona y lo que deja de ganar.", "Compara los resultados con un ingreso familiar ficticio y muestra qué porcentaje pesa cada caso. El resultado puede ser un cuadro comparativo y una nota con tus conclusiones."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "estudia qué ayudas o seguros existen y qué parte del costo cubren en cada caso."}, {"titulo": "Otro formato", "aporta": "crea una calculadora sencilla en una hoja de cálculo para que cualquiera estime el costo de su caso."}, {"titulo": "Un paso más", "aporta": "analiza qué pasa cuando el gasto de salud se repite cada mes, como en una enfermedad crónica."}], "objetivos": ["Estimar el costo completo de una atención.", "Comparar costos entre distintas vías de atención.", "Relacionar los costos con un ingreso familiar.", "Presentar las conclusiones con claridad."], "habilidades": ["Cálculo de costos.", "Análisis comparativo.", "Lectura de datos públicos.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Portales de precios y tarifas públicas.", "Documento o presentación."], "lineamientos": ["Usa precios públicos o ficticios y familias inventadas; no pidas a nadie que comparta sus gastos reales de salud.", "No recomiendes dónde atenderse: describe lo que cuesta cada vía y las limitaciones de tu análisis."], "otroSector": "El mismo cálculo sirve para el costo real de estudiar, mudarse o emprender un negocio."}$f07sld$::jsonb,7),
('como-se-distribuyen-los-servicios-de-salud-en-tu-ciudad','salud',array['ciudades']::text[],'¿Cómo se distribuyen los servicios de salud en tu ciudad?','Ubica en un mapa los servicios de salud de tu zona y descubre quiénes quedan cerca, quiénes lejos y dónde haría falta uno más.','Análisis','~25 h',25,array['Mapas','Datos']::text[],array['investigar','crear']::text[],'publicos',NULL,'ingenieria civil arquitectura ingenieria de sistemas estadistica trabajo social medicina ingenieria industrial sociologia lectura y construccion de mapas. analisis de datos publicos. pensamiento espacial. presentacion de resultados. mapas en linea, como los de uso libre. hoja de calculo. portales de datos abiertos de salud y de tu gobierno regional.',$f08sld${"id": "como-se-distribuyen-los-servicios-de-salud-en-tu-ciudad", "area": "salud", "areas2": ["ciudades"], "titulo": "¿Cómo se distribuyen los servicios de salud en tu ciudad?", "resumen": "Ubica en un mapa los servicios de salud de tu zona y descubre quiénes quedan cerca, quiénes lejos y dónde haría falta uno más.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Mapas", "Datos"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Ingeniería Civil", "Arquitectura", "Ingeniería de Sistemas", "Estadística", "Trabajo Social", "Medicina", "Ingeniería Industrial", "Sociología"], "problema": ["Casi todos sabemos dónde queda «el hospital», pero casi nadie sabe cuántos servicios hay en su zona, de qué tipo son, cómo se llega ni qué tan lejos quedan para quienes viven en los extremos.", "Cuando los servicios se concentran en pocas zonas, algunas personas tienen todo a pocas cuadras y otras deben viajar horas. Sin un mapa, esa desigualdad no se ve."], "desarrollar": ["Reúne de fuentes públicas la ubicación de los servicios de salud de un distrito o una ciudad y colócalos en un mapa. Estima cuánto tardaría en llegar una persona desde distintos puntos, caminando o en transporte público.", "Marca las zonas más alejadas y explica por qué importan. El resultado puede ser un mapa comentado con las zonas bien y mal cubiertas, y una propuesta de dónde priorizar."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "cruza el mapa con la población de cada zona para ver cuántas personas hay por servicio."}, {"titulo": "Otro formato", "aporta": "crea una versión interactiva del mapa, con filtros por tipo de servicio."}, {"titulo": "Un paso más", "aporta": "añade los horarios y los servicios que se ofrecen, para ver qué hay realmente abierto a cada hora."}], "objetivos": ["Reunir la ubicación de los servicios de salud de una zona.", "Representarlos en un mapa claro.", "Estimar tiempos de llegada.", "Identificar zonas con poca cobertura."], "habilidades": ["Lectura y construcción de mapas.", "Análisis de datos públicos.", "Pensamiento espacial.", "Presentación de resultados."], "herramientas": ["Mapas en línea, como los de uso libre.", "Hoja de cálculo.", "Portales de datos abiertos de salud y de tu gobierno regional."], "lineamientos": ["Usa solo información pública y verifica que esté actualizada; indica la fecha de la que obtuviste cada dato.", "No juzgues la calidad de un establecimiento por su ubicación: tu análisis trata de cercanía, no de atención."], "otroSector": "La misma técnica sirve para ubicar colegios, bomberos, mercados, paraderos o puntos de reciclaje."}$f08sld$::jsonb,8),
('tu-informacion-medica-en-un-solo-lugar-y-en-orden','salud',array['tecnologia']::text[],'Tu información médica en un solo lugar y en orden','Diseña una forma sencilla de guardar y presentar la información médica personal, como alergias, controles y medicamentos, de modo que sirva en una emergencia y no se pierda.','Prototipo','~15 h',15,array['Organización','Datos personales']::text[],array['crear','resolver']::text[],'ficticios',NULL,'ingenieria de sistemas ingenieria de software medicina enfermeria administracion diseno grafico derecho ingenieria industrial organizacion de informacion. diseno de formularios. privacidad de datos personales. pensamiento centrado en el usuario. hoja de calculo o editor de documentos. herramientas de maquetas. gestor de archivos o carpetas.',$f09sld${"id": "tu-informacion-medica-en-un-solo-lugar-y-en-orden", "area": "salud", "areas2": ["tecnologia"], "titulo": "Tu información médica en un solo lugar y en orden", "resumen": "Diseña una forma sencilla de guardar y presentar la información médica personal, como alergias, controles y medicamentos, de modo que sirva en una emergencia y no se pierda.", "tipo": "Prototipo", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Organización", "Datos personales"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Medicina", "Enfermería", "Administración", "Diseño Gráfico", "Derecho", "Ingeniería Industrial"], "problema": ["Los datos médicos de una persona suelen estar dispersos: recetas en un cajón, resultados en otro, fechas en la memoria. En una consulta o una emergencia, esa información es difícil de reunir y a menudo se cuenta incompleta.", "Guardarla también tiene sus riesgos: es información sensible que no debería quedar a la vista ni en cualquier lugar."], "desarrollar": ["Define qué información básica tendría sentido llevar siempre consigo y cómo organizarla: datos de contacto, controles, medicamentos, antecedentes. Diseña con datos inventados una ficha personal y una forma de mantenerla al día.", "El resultado puede ser una plantilla impresa, una hoja de cálculo o una maqueta de aplicación. Incluye cómo decidir quién puede ver qué."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta la ficha para una familia, un adulto mayor o un niño con necesidades especiales."}, {"titulo": "Otra mirada", "aporta": "compara qué datos sirven en una emergencia y cuáles solo importan en un control rutinario."}, {"titulo": "Un paso más", "aporta": "piensa cómo hacer que la ficha sea fácil de actualizar para que no quede obsoleta."}], "objetivos": ["Identificar qué información médica conviene tener organizada.", "Diseñar una ficha clara y fácil de actualizar.", "Decidir quién puede ver cada dato.", "Probarla con un caso inventado."], "habilidades": ["Organización de información.", "Diseño de formularios.", "Privacidad de datos personales.", "Pensamiento centrado en el usuario."], "herramientas": ["Hoja de cálculo o editor de documentos.", "Herramientas de maquetas.", "Gestor de archivos o carpetas."], "lineamientos": ["Usa datos totalmente inventados en el material que compartas: nunca información médica real de nadie, tampoco la tuya.", "Explica que la ficha complementa, no reemplaza, la historia clínica de un servicio de salud."], "otroSector": "La misma idea sirve para organizar los datos de un vehículo, de una mascota, de una vivienda o de un negocio."}$f09sld$::jsonb,9),
('medicamentos-en-casa-cuantos-se-vencen-sin-usarse','salud',array['ambiente']::text[],'Medicamentos en casa: ¿cuántos se vencen sin usarse?','Revisa qué hay en un botiquín, cuánto se desperdicia y cómo evitar que los medicamentos se venzan o terminen en el lugar equivocado.','Análisis','~12 h',12,array['Hogar','Sostenibilidad','Prevención']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental ingenieria industrial medicina enfermeria nutricion administracion educacion comunicaciones inventario y control. analisis basico de datos. educacion ambiental. comunicacion clara. hoja de calculo. etiquetas o plantillas imprimibles. herramientas para disenar carteles.',$f10sld${"id": "medicamentos-en-casa-cuantos-se-vencen-sin-usarse", "area": "salud", "areas2": ["ambiente"], "titulo": "Medicamentos en casa: ¿cuántos se vencen sin usarse?", "resumen": "Revisa qué hay en un botiquín, cuánto se desperdicia y cómo evitar que los medicamentos se venzan o terminen en el lugar equivocado.", "tipo": "Análisis", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Hogar", "Sostenibilidad", "Prevención"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Ingeniería Ambiental", "Ingeniería Industrial", "Medicina", "Enfermería", "Nutrición", "Administración", "Educación", "Comunicaciones"], "problema": ["Casi todos los hogares tienen un botiquín con pastillas sobrantes, jarabes abiertos o cremas que ya no se usan. Algunos están vencidos y otros se guardan donde no deben: en el calor, al alcance de niños o sin su caja.", "Qué hacer con ellos tampoco es claro: muchas personas los botan a la basura común o al desagüe sin saber que eso puede dañar el ambiente o ser peligroso."], "desarrollar": ["Con permiso, haz un inventario del botiquín de tu casa o inventa uno: qué hay, para qué sirve, cuándo vence y cómo está guardado. Calcula cuántos vencieron o están a punto de hacerlo, y qué parte podría haberse evitado comprando o guardando mejor.", "Con eso propón un sistema sencillo de control de fechas y una guía de qué hacer con lo vencido según las normas de tu localidad. El resultado puede ser una hoja de control y un cartel."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "estima cuánto dinero se pierde al año en medicamentos que se vencen sin usarse."}, {"titulo": "Otro formato", "aporta": "crea un aviso que alerte cuando algo esté por vencer."}, {"titulo": "Un paso más", "aporta": "investiga si en tu zona existen puntos de recolección de medicamentos vencidos y cómo se informa a la gente."}], "objetivos": ["Hacer un inventario ordenado de un botiquín.", "Estimar cuánto se desperdicia por vencimiento.", "Diseñar un sistema simple de control.", "Informar qué hacer con lo vencido."], "habilidades": ["Inventario y control.", "Análisis básico de datos.", "Educación ambiental.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Etiquetas o plantillas imprimibles.", "Herramientas para diseñar carteles."], "lineamientos": ["No pruebes, recomiendes ni combines medicamentos: el ejercicio es de orden y de fechas, no de uso. Si alguien tiene dudas, debe consultar a un profesional de la salud.", "Trabaja con lo que haya en tu casa o con un botiquín inventado, y pide permiso antes de revisar el de otra persona."], "otroSector": "El mismo análisis sirve para despensas, productos de limpieza, pinturas o repuestos con fecha de caducidad."}$f10sld$::jsonb,10),
('senales-de-agotamiento-como-reconocerlo-antes-de-llegar-al-limite','salud',array['educacion']::text[],'Señales de agotamiento: ¿cómo reconocerlo antes de llegar al límite?','Elabora una guía que ayude a notar a tiempo las señales de agotamiento físico y emocional, en estudios o en el trabajo, y a saber cuándo buscar orientación.','Guía','~15 h',15,array['Bienestar','Prevención','Estrés']::text[],array['resolver','crear']::text[],'ficticios',NULL,'psicologia medicina enfermeria educacion trabajo social comunicaciones administracion ingenieria industrial busqueda de informacion confiable. redaccion clara y empatica. diseno de materiales. pensamiento critico sobre el bienestar. documento, presentacion o infografia. formularios en linea para la prueba. herramientas de diseno.',$f11sld${"id": "senales-de-agotamiento-como-reconocerlo-antes-de-llegar-al-limite", "area": "salud", "areas2": ["educacion"], "titulo": "Señales de agotamiento: ¿cómo reconocerlo antes de llegar al límite?", "resumen": "Elabora una guía que ayude a notar a tiempo las señales de agotamiento físico y emocional, en estudios o en el trabajo, y a saber cuándo buscar orientación.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Bienestar", "Prevención", "Estrés"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Psicología", "Medicina", "Enfermería", "Educación", "Trabajo Social", "Comunicaciones", "Administración", "Ingeniería Industrial"], "problema": ["El agotamiento rara vez aparece de golpe: primero hay cansancio que no se va, irritación, falta de ganas, problemas para dormir o para concentrarse. Como cada señal parece pequeña, se normaliza hasta que ya pesa mucho.", "En épocas de alta demanda, como exámenes o entregas, es todavía más difícil detectarlo, porque todos están cansados y nadie quiere parecer débil."], "desarrollar": ["Recoge de fuentes confiables, como organismos de salud o universidades, las señales más comunes y agrúpalas por tipo: del cuerpo, de las emociones, de la conducta y de los estudios o el trabajo. Escríbelas con ejemplos cotidianos, no con términos técnicos.", "Arma con eso una guía de una página o un cuestionario breve de autorreflexión, que no dé un diagnóstico y que indique qué hacer o a quién acudir cuando las señales se acumulan. Pruébala con alguien cercano para ver si se entiende."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta la guía para docentes, cuidadores o personas que trabajan por turnos."}, {"titulo": "Otro formato", "aporta": "convierte la guía en una campaña corta para redes o para un panel dentro de una universidad."}, {"titulo": "Una prueba", "aporta": "revisa con personas voluntarias qué señales les resultan más fáciles de reconocer y cuáles pasan desapercibidas."}], "objetivos": ["Identificar las señales comunes de agotamiento.", "Explicarlas con ejemplos cotidianos.", "Indicar cuándo y dónde buscar orientación.", "Probar la guía con otras personas."], "habilidades": ["Búsqueda de información confiable.", "Redacción clara y empática.", "Diseño de materiales.", "Pensamiento crítico sobre el bienestar."], "herramientas": ["Documento, presentación o infografía.", "Formularios en línea para la prueba.", "Herramientas de diseño."], "lineamientos": ["La guía orienta, no diagnostica: no uses términos médicos como si fueran un resultado ni digas a nadie que «tiene» una condición. Indica siempre dónde conseguir ayuda profesional.", "Si durante la prueba alguien cuenta algo delicado, escúchalo con respeto, no lo registres y sugiérele hablar con un profesional o con alguien de confianza."], "otroSector": "La misma guía sirve para equipos de trabajo, deportistas, cuidadores o personas que atienden público."}$f11sld$::jsonb,11),
('que-influye-en-la-salud-mental-de-los-estudiantes-universitarios','salud',array['educacion']::text[],'¿Qué influye en la salud mental de los estudiantes universitarios?','Explora qué factores del entorno universitario, como la carga, el dinero, el tiempo o el apoyo, se relacionan con el bienestar emocional de los estudiantes y qué podría ayudar.','Investigación','~25 h',25,array['Salud mental','Estudiantes']::text[],array['investigar','resolver']::text[],'publicos',NULL,'psicologia medicina educacion sociologia trabajo social estadistica comunicaciones administracion lectura critica de estudios. analisis de informacion. sintesis y redaccion. sensibilidad frente a temas delicados. buscadores academicos y portales de organismos de salud. hoja de calculo. documento o presentacion.',$f12sld${"id": "que-influye-en-la-salud-mental-de-los-estudiantes-universitarios", "area": "salud", "areas2": ["educacion"], "titulo": "¿Qué influye en la salud mental de los estudiantes universitarios?", "resumen": "Explora qué factores del entorno universitario, como la carga, el dinero, el tiempo o el apoyo, se relacionan con el bienestar emocional de los estudiantes y qué podría ayudar.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Salud mental", "Estudiantes"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Psicología", "Medicina", "Educación", "Sociología", "Trabajo Social", "Estadística", "Comunicaciones", "Administración"], "problema": ["La universidad reúne muchas fuentes de presión a la vez: exámenes, trabajo, traslados largos, dinero y la sensación de tener que rendir. Muchas personas lo sufren en silencio y creen que son las únicas.", "Se habla de salud mental en general, pero casi no se estudian los factores concretos del entorno que se pueden cambiar, como los horarios, la forma de evaluar o la información sobre dónde pedir ayuda."], "desarrollar": ["Revisa estudios públicos y reportes de universidades u organismos de salud, y agrupa los factores que se mencionan más: académicos, económicos, sociales y de hábitos. Elige tres que se puedan mejorar desde una universidad y explica qué cambios serían realistas.", "El resultado puede ser un informe breve con un mapa de factores y una propuesta de mejoras que una universidad podría aplicar sin grandes inversiones."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara qué factores pesan más en el primer ciclo, a mitad de carrera y al final."}, {"titulo": "Otro formato", "aporta": "convierte los hallazgos en una infografía para estudiantes con consejos y recursos de ayuda."}, {"titulo": "Un paso más", "aporta": "revisa qué servicios de apoyo existen en tu universidad y qué tan fáciles de encontrar son."}], "objetivos": ["Identificar los factores que se asocian al bienestar emocional.", "Distinguir los que se pueden cambiar.", "Proponer mejoras realistas.", "Presentar los hallazgos con respeto y claridad."], "habilidades": ["Lectura crítica de estudios.", "Análisis de información.", "Síntesis y redacción.", "Sensibilidad frente a temas delicados."], "herramientas": ["Buscadores académicos y portales de organismos de salud.", "Hoja de cálculo.", "Documento o presentación."], "lineamientos": ["Trabaja con estudios públicos y datos agregados, no con relatos individuales identificables. No pidas a nadie que cuente su experiencia personal sobre este tema.", "No hagas diagnósticos ni digas qué causa la depresión o la ansiedad de nadie: este proyecto describe factores del entorno. Incluye siempre cómo y dónde pedir ayuda."], "otroSector": "El mismo enfoque sirve para estudiar el bienestar en una empresa, un hospital o una escuela."}$f12sld$::jsonb,12),
('un-programa-de-habitos-saludables-para-un-grupo-concreto','salud',array['educacion']::text[],'Un programa de hábitos saludables para un grupo concreto','Diseña un programa pequeño para que un grupo específico, como estudiantes, vigilantes o personas mayores, adopte un par de hábitos saludables y los mantenga.','Plan','~30 h',30,array['Programas','Hábitos','Bienestar']::text[],array['crear','resolver']::text[],'ficticios',NULL,'trabajo social psicologia medicina enfermeria nutricion educacion administracion comunicaciones diseno de programas. observacion de rutinas. planificacion de actividades. evaluacion con indicadores sencillos. hoja de calculo o calendario. documento o presentacion. herramientas para disenar materiales.',$f13sld${"id": "un-programa-de-habitos-saludables-para-un-grupo-concreto", "area": "salud", "areas2": ["educacion"], "titulo": "Un programa de hábitos saludables para un grupo concreto", "resumen": "Diseña un programa pequeño para que un grupo específico, como estudiantes, vigilantes o personas mayores, adopte un par de hábitos saludables y los mantenga.", "tipo": "Plan", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Programas", "Hábitos", "Bienestar"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Trabajo Social", "Psicología", "Medicina", "Enfermería", "Nutrición", "Educación", "Administración", "Comunicaciones"], "problema": ["Los programas de bienestar fracasan cuando se hacen para «todos»: una charla general no cambia lo que hace una persona con turnos de noche o un adolescente con exámenes. Los hábitos dependen del horario, el dinero, el lugar y las ganas de cada grupo.", "Además, muchos programas comienzan con entusiasmo y terminan a las pocas semanas, sin que nadie sepa si sirvieron."], "desarrollar": ["Elige un grupo concreto y conoce sus rutinas por observación, lectura o conversaciones breves. Define uno o dos hábitos realistas, como moverse más, tomar agua o dormir mejor, y diseña un programa de cuatro a seis semanas con actividades pequeñas, responsables y una forma de motivar.", "Incluye cómo saber si funcionó, con indicadores simples. El resultado puede ser un plan con calendario, materiales y una hoja de seguimiento, que puedas probar con un grupo pequeño."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "adapta el programa a dos grupos distintos y compara qué debió cambiar."}, {"titulo": "Un paso más", "aporta": "incorpora algo para que los participantes se apoyen entre sí."}, {"titulo": "Una prueba", "aporta": "aplica una semana del programa con voluntarios y ajusta según lo que no resultó."}], "objetivos": ["Conocer las rutinas y necesidades de un grupo.", "Elegir hábitos realistas.", "Diseñar un programa con actividades y calendario.", "Definir cómo evaluar si funciona."], "habilidades": ["Diseño de programas.", "Observación de rutinas.", "Planificación de actividades.", "Evaluación con indicadores sencillos."], "herramientas": ["Hoja de cálculo o calendario.", "Documento o presentación.", "Herramientas para diseñar materiales."], "lineamientos": ["Si pruebas el programa con personas, que sea con su consentimiento, sin datos médicos y sin presionar a nadie. Haz recomendaciones generales, no planes de dieta ni de ejercicio personalizados.", "Los hábitos que propongas deben ser seguros para cualquiera; si alguien tiene una condición de salud, que lo consulte con su profesional."], "otroSector": "El mismo diseño sirve para programas de seguridad, de ahorro, de estudio o de convivencia."}$f13sld$::jsonb,13),
('como-cambian-tus-habitos-de-sueno-en-una-semana','salud',array['tecnologia']::text[],'¿Cómo cambian tus hábitos de sueño en una semana?','Registra durante una semana cuándo duermes, cuándo te despiertas y cómo te sientes, y descubre qué patrones aparecen y qué cambia entre días de estudio y de descanso.','Análisis','~10 h',10,array['Sueño','Registro de hábitos','Datos']::text[],array['investigar','crear']::text[],'propios',NULL,'psicologia medicina estadistica ingenieria de sistemas ingenieria industrial educacion diseno grafico nutricion registro y organizacion de datos. analisis basico y graficos. observacion de habitos. comunicacion de resultados. hoja de calculo. aplicacion de notas o cuaderno. herramientas para crear graficos.',$f14sld${"id": "como-cambian-tus-habitos-de-sueno-en-una-semana", "area": "salud", "areas2": ["tecnologia"], "titulo": "¿Cómo cambian tus hábitos de sueño en una semana?", "resumen": "Registra durante una semana cuándo duermes, cuándo te despiertas y cómo te sientes, y descubre qué patrones aparecen y qué cambia entre días de estudio y de descanso.", "tipo": "Análisis", "tiempo": "~10 h", "horas": 10, "etiquetas": ["Sueño", "Registro de hábitos", "Datos"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Psicología", "Medicina", "Estadística", "Ingeniería de Sistemas", "Ingeniería Industrial", "Educación", "Diseño Gráfico", "Nutrición"], "problema": ["Casi todos creemos saber cuánto dormimos, pero pocas veces lo medimos. Los horarios cambian entre semana y fin de semana, y el cansancio del día no siempre se relaciona con lo que imaginamos.", "Sin datos, es difícil entender qué hábito pesa más: acostarse tarde, usar el celular, las comidas, los horarios de estudio o simplemente la rutina de cada día."], "desarrollar": ["Diseña un registro sencillo para anotar durante siete días la hora de acostarte, de dormirte, de despertarte y una calificación de cómo te sientes. Si puedes, suma datos del día, como hora de la última pantalla o de la cena.", "Al terminar, busca patrones con una hoja de cálculo o gráficos simples y descríbelos. El resultado puede ser un informe corto con tus hallazgos y una propuesta de cambio pequeño para probar la semana siguiente."], "ampliaciones": [{"titulo": "Una prueba", "aporta": "cambia un solo hábito la semana siguiente y compara los resultados con la primera."}, {"titulo": "Otro formato", "aporta": "convierte tu registro en una plantilla que otras personas puedan usar."}, {"titulo": "Otra mirada", "aporta": "compara tu registro con el de otras personas que acepten participar, sin identificarlas."}], "objetivos": ["Diseñar un registro de sueño fácil de llenar.", "Registrar los datos durante una semana.", "Buscar patrones con gráficos simples.", "Proponer un cambio pequeño para probar."], "habilidades": ["Registro y organización de datos.", "Análisis básico y gráficos.", "Observación de hábitos.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Aplicación de notas o cuaderno.", "Herramientas para crear gráficos."], "lineamientos": ["Trabaja con tus propios datos o con los de personas que acepten participar; no reveles quién es cada una. No interpretes los resultados como un diagnóstico de ningún problema de sueño.", "Si dormir mal te preocupa, consulta con un profesional de la salud: este proyecto solo observa hábitos, no trata trastornos."], "otroSector": "El mismo método sirve para registrar gastos, tiempo de estudio, estado de ánimo o consumo de energía."}$f14sld$::jsonb,14),
('pantallas-y-descanso-que-relacion-hay','salud',array['sociedad']::text[],'Pantallas y descanso: ¿qué relación hay?','Revisa qué dice la evidencia sobre el uso de pantallas antes de dormir y durante el día, y propone hábitos realistas que ayuden a descansar mejor.','Investigación','~15 h',15,array['Hábitos digitales','Sueño','Bienestar']::text[],array['investigar','resolver']::text[],'publicos',NULL,'psicologia medicina ingenieria de sistemas comunicaciones educacion sociologia estadistica diseno grafico lectura critica de evidencia. comunicacion de ciencia al publico. sintesis de informacion. diseno de materiales. buscadores academicos y portales de organismos de salud. documento o presentacion. herramientas de diseno.',$f15sld${"id": "pantallas-y-descanso-que-relacion-hay", "area": "salud", "areas2": ["sociedad"], "titulo": "Pantallas y descanso: ¿qué relación hay?", "resumen": "Revisa qué dice la evidencia sobre el uso de pantallas antes de dormir y durante el día, y propone hábitos realistas que ayuden a descansar mejor.", "tipo": "Investigación", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Hábitos digitales", "Sueño", "Bienestar"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Psicología", "Medicina", "Ingeniería de Sistemas", "Comunicaciones", "Educación", "Sociología", "Estadística", "Diseño Gráfico"], "problema": ["Casi todos usamos el celular hasta último minuto antes de dormir, y es frecuente escuchar que «la luz azul» o las redes sociales dañan el sueño. Pero no todo lo que se dice está comprobado, y los efectos cambian según el uso.", "Las recomendaciones suelen ser tajantes y poco realistas, como «no uses el celular de noche», y por eso nadie las sigue."], "desarrollar": ["Reúne tres o cuatro fuentes confiables sobre pantallas y descanso y separa lo que está bien establecido de lo que aún se discute. Distingue tipos de uso: mirar videos, chatear, estudiar o leer.", "Con eso arma una guía práctica con opciones realistas para distintos estilos de vida. El resultado puede ser una guía o un cartel que explique qué se sabe, qué no y qué se puede probar sin sacrificar lo que hace cada persona con su celular."], "ampliaciones": [{"titulo": "Una prueba", "aporta": "prueba una semana con una regla sencilla y registra cómo cambia el descanso."}, {"titulo": "Otra mirada", "aporta": "compara qué recomendaciones funcionan mejor para personas que estudian de noche o trabajan por turnos."}, {"titulo": "Otro formato", "aporta": "convierte la guía en un video corto o una serie de mensajes para compartir."}], "objetivos": ["Diferenciar lo comprobado de lo que se discute.", "Distinguir tipos de uso de pantallas.", "Elaborar recomendaciones realistas.", "Presentarlas sin exagerar ni asustar."], "habilidades": ["Lectura crítica de evidencia.", "Comunicación de ciencia al público.", "Síntesis de información.", "Diseño de materiales."], "herramientas": ["Buscadores académicos y portales de organismos de salud.", "Documento o presentación.", "Herramientas de diseño."], "lineamientos": ["Cita las fuentes y no presentes como seguro lo que es discutible; señala los límites de lo que se sabe.", "No uses un tono alarmista ni culpes a las personas por su uso del celular. Si alguien tiene problemas serios de sueño, que consulte a un profesional."], "otroSector": "El mismo análisis sirve para estudiar videojuegos, redes sociales, televisión o el uso de computadoras en una oficina."}$f15sld$::jsonb,15),
('como-afectan-los-horarios-irregulares-a-la-salud','salud',array['negocios']::text[],'¿Cómo afectan los horarios irregulares a la salud?','Explora cómo los turnos de noche, los horarios rotativos o los cambios constantes influyen en el cansancio, la alimentación y el ánimo, y qué podrían hacer las personas y las organizaciones.','Investigación','~20 h',20,array['Trabajo','Horarios','Bienestar']::text[],array['investigar','resolver']::text[],'publicos',NULL,'administracion ingenieria industrial psicologia medicina enfermeria sociologia derecho estadistica analisis de informacion. gestion de turnos y horarios. redaccion de propuestas. comprension del bienestar laboral. hoja de calculo. documento o presentacion. fuentes de organismos de salud y de trabajo.',$f16sld${"id": "como-afectan-los-horarios-irregulares-a-la-salud", "area": "salud", "areas2": ["negocios"], "titulo": "¿Cómo afectan los horarios irregulares a la salud?", "resumen": "Explora cómo los turnos de noche, los horarios rotativos o los cambios constantes influyen en el cansancio, la alimentación y el ánimo, y qué podrían hacer las personas y las organizaciones.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Trabajo", "Horarios", "Bienestar"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Administración", "Ingeniería Industrial", "Psicología", "Medicina", "Enfermería", "Sociología", "Derecho", "Estadística"], "problema": ["Mucha gente trabaja o estudia en horarios que cambian cada semana: turnos de noche, guardias, clases en horas distintas. El cuerpo se acostumbra mal, y el descanso, las comidas y la vida social se desordenan.", "Las organizaciones suelen armar los horarios pensando en la producción y no en el bienestar, y cuando alguien se agota se atribuye a falta de disciplina."], "desarrollar": ["Revisa información pública sobre trabajo por turnos y horarios irregulares y arma el perfil de tres personas inventadas con rutinas distintas. Para cada una, describe qué hábitos se desordenan y qué ajustes podrían ayudar.", "Luego propón dos o tres medidas que una organización podría aplicar, como turnos más estables o descansos mejor ubicados. El resultado puede ser un informe breve con los perfiles y las propuestas."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "estima qué cuesta a una organización el ausentismo o los errores por cansancio."}, {"titulo": "Otro público", "aporta": "adapta el análisis a estudiantes que estudian y trabajan a la vez."}, {"titulo": "Un paso más", "aporta": "diseña un horario de ejemplo que reduzca el desgaste sin perder la producción."}], "objetivos": ["Describir cómo los horarios irregulares alteran los hábitos.", "Construir perfiles de personas con rutinas distintas.", "Proponer ajustes personales y organizacionales.", "Presentar las ideas con respaldo de fuentes públicas."], "habilidades": ["Análisis de información.", "Gestión de turnos y horarios.", "Redacción de propuestas.", "Comprensión del bienestar laboral."], "herramientas": ["Hoja de cálculo.", "Documento o presentación.", "Fuentes de organismos de salud y de trabajo."], "lineamientos": ["Usa perfiles inventados y datos públicos; no pidas datos de salud a trabajadores reales.", "Presenta las recomendaciones como ideas generales: lo que conviene a cada persona depende de su situación y de lo que indique un profesional de la salud."], "otroSector": "El mismo análisis sirve para equipos de seguridad, transporte, atención al cliente, hospitales o fábricas con turnos."}$f16sld$::jsonb,16),
('que-hace-dificil-mantener-un-habito-saludable','salud',array['sociedad']::text[],'¿Qué hace difícil mantener un hábito saludable?','Descubre por qué tantas personas empiezan una rutina de ejercicio, una dieta o un horario sano y a las pocas semanas la dejan, y qué ayuda a sostenerla.','Investigación','~20 h',20,array['Hábitos','Comportamiento']::text[],array['investigar','resolver']::text[],'publicos',NULL,'psicologia medicina nutricion educacion sociologia trabajo social comunicaciones administracion analisis de comportamiento. investigacion de informacion. diseno de estrategias. comunicacion empatica. hoja de calculo. formularios en linea. documento o presentacion.',$f17sld${"id": "que-hace-dificil-mantener-un-habito-saludable", "area": "salud", "areas2": ["sociedad"], "titulo": "¿Qué hace difícil mantener un hábito saludable?", "resumen": "Descubre por qué tantas personas empiezan una rutina de ejercicio, una dieta o un horario sano y a las pocas semanas la dejan, y qué ayuda a sostenerla.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Hábitos", "Comportamiento"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Psicología", "Medicina", "Nutrición", "Educación", "Sociología", "Trabajo Social", "Comunicaciones", "Administración"], "problema": ["Cada enero y cada lunes mucha gente decide hacer ejercicio, comer mejor o dormir más. A las pocas semanas casi todo se abandona, y la explicación habitual es «falta de voluntad».", "Eso rara vez es la causa: influyen el cansancio, el dinero, el entorno, la compañía, los horarios y que el hábito sea demasiado grande, aburrido o difícil de empezar. Sin entender esas razones, los consejos no sirven."], "desarrollar": ["Reúne estudios públicos y conversaciones breves y anónimas con personas voluntarias, y arma un mapa de las razones por las que se abandona un hábito saludable. Agrúpalas en categorías, como tiempo, dinero, entorno, motivación y apoyo.", "Para cada categoría, plantea una estrategia pequeña que ayude. El resultado puede ser un informe corto o una guía con ideas para sostener un hábito, probadas con una persona."], "ampliaciones": [{"titulo": "Una prueba", "aporta": "acompaña a una persona voluntaria dos semanas aplicando una de las estrategias y registra qué ocurrió."}, {"titulo": "Otra mirada", "aporta": "compara qué ayuda más a mantener un hábito: recordatorios, compañía, recompensas o simplificarlo."}, {"titulo": "Otro formato", "aporta": "diseña una tarjeta o un juego que ayude a elegir una estrategia según la situación de cada persona."}], "objetivos": ["Identificar las razones por las que se abandonan los hábitos.", "Agruparlas en categorías.", "Proponer estrategias pequeñas para cada categoría.", "Probar una estrategia con una persona."], "habilidades": ["Análisis de comportamiento.", "Investigación de información.", "Diseño de estrategias.", "Comunicación empática."], "herramientas": ["Hoja de cálculo.", "Formularios en línea.", "Documento o presentación."], "lineamientos": ["Las conversaciones deben ser voluntarias y anónimas; no anotes datos de salud de nadie. Las estrategias son ideas generales, no planes médicos ni de entrenamiento.", "Evita culpar a las personas: muchas veces el hábito falla por el entorno, no por la persona."], "otroSector": "El mismo análisis sirve para entender por qué se abandonan los estudios, el ahorro, un curso en línea o un voluntariado."}$f17sld$::jsonb,17)
